-- GENERATED by investigations/probe-suggested-places.js -- do not edit; run that.
--
-- « Lieux proposés », day 2: the statements maps-shim sends that only the
-- live database can run (PostGIS, the place index, movin.place_type_of), run
-- on the live database before the release. Read-only for every real table:
-- writes go to pg_temp only (this session's schema, gone when psql exits).
--
--   scp investigations/probe-suggested-places.sql ny:/tmp/
--   ssh ny 'docker exec -i ny-postgres psql -U postgres -d atlas_dev -X -q < /tmp/probe-suggested-places.sql' | tee ~/probe-suggested-places.log
--
-- What to read in the log: each « --- » line is one call the shim will make,
-- with its answer and its time. Every statement must run (ON_ERROR_STOP);
-- the expected answers are written in the line before each.

\set ON_ERROR_STOP on
\pset footer off
SET statement_timeout = '60s';
\timing on

\echo '=== 0. a copy of the table, in pg_temp, with day 2''s locality and four test proposals'
CREATE TEMP TABLE suggested_place (LIKE movin.suggested_place INCLUDING ALL);
ALTER TABLE pg_temp.suggested_place ADD COLUMN IF NOT EXISTS locality text;
INSERT INTO pg_temp.suggested_place
       (proposed_name, proposed_type, name, type, name_ar, lat, lon, country, locality,
        author_side, author_id, status, decided_at, decided_by_email)
SELECT v.n, v.t, v.n, v.t, v.ar, v.lat, v.lon, v.c,
       geo.locality_of(st_setsrid(st_makepoint(v.lon, v.lat), 4326)::geography),
       'rider', 'probe', v.s,
       CASE WHEN v.s = 'approved' THEN now() END,
       CASE WHEN v.s = 'approved' THEN 'probe@mova' END
  FROM (VALUES
    ('Café Sonde Tfeila',     'cafe',     'مقهى المسبار',   18.0901::float8, -15.9702::float8, 'MR', 'approved'),
    ('Marché Sonde Ksar',     'market',   NULL,             18.1105,         -15.9512,         'MR', 'approved'),
    ('Pharmacie Sonde Hydra', 'pharmacy', 'صيدلية المسبار', 36.7425,           3.0434,         'DZ', 'approved'),
    ('Café Sonde En Attente', 'cafe',     NULL,             18.0870,         -15.9760,         'MR', 'pending')
  ) v(n, t, ar, lat, lon, c, s)
 ORDER BY v.n = 'Café Sonde En Attente', v.lat;
SELECT place_id, name, type, status, country, locality FROM pg_temp.suggested_place ORDER BY id;

\echo '=== 1. countryAt: MR, DZ, MR, DZ, then NO ROW for Rabat (outside both)'
PREPARE country_at AS
  SELECT CASE region WHEN 'Algeria' THEN 'DZ' ELSE 'MR' END AS country
  FROM atlas_app.geometry
  WHERE region IN ('Algeria', 'Mauritania')
  AND st_contains(geom, st_point($2::float8, $1::float8))
  LIMIT 1;
\echo '--- Nouakchott'
EXECUTE country_at(18.0858, -15.9785);
\echo '--- Algiers'
EXECUTE country_at(36.7538, 3.0588);
\echo '--- Nouadhibou'
EXECUTE country_at(20.9420, -17.0362);
\echo '--- Tamanrasset'
EXECUTE country_at(22.7850, 5.5228);
\echo '--- Rabat (expect no row)'
EXECUTE country_at(34.0209, -6.8416);

\echo '=== 2. localityAt: a town or district for each, possibly NULL in the empty desert'
PREPARE locality_at AS
  SELECT geo.locality_of(st_setsrid(st_makepoint($2::float8, $1::float8), 4326)::geography) AS locality;
\echo '--- Nouakchott'
EXECUTE locality_at(18.0858, -15.9785);
\echo '--- Algiers'
EXECUTE locality_at(36.7538, 3.0588);
\echo '--- Tamanrasset'
EXECUTE locality_at(22.7850, 5.5228);
\echo '--- the desert, 23.5 N 12 W'
EXECUTE locality_at(23.5, -12.0);

\echo '=== 3. osmNear (the duplicate test): OSM places within 100 m of each centre'
PREPARE osm_near AS
  SELECT place_id, display_name, alt_names, name_ar, lat, lon
  FROM geo.place
  WHERE st_dwithin(geog, st_setsrid(st_makepoint($2::float8, $1::float8), 4326)::geography, $3)
  LIMIT 200;
\echo '--- Nouakchott, 100 m'
EXECUTE osm_near(18.0858, -15.9785, 100);
\echo '--- Algiers, 100 m'
EXECUTE osm_near(36.7538, 3.0588, 100);

\echo '=== 4. osmOfType (search by type): 5 km first, 15 km when 5 finds nothing'
PREPARE osm_of_type AS
  SELECT p.place_id, p.display_name, p.name_ar, p.locality, l.name_ar AS locality_ar,
  p.lat, p.lon, st_distance(p.geog, st_setsrid(st_makepoint($3::float8, $2::float8), 4326)::geography, false) AS distance_m
  FROM geo.place p
  LEFT JOIN LATERAL (
  SELECT l2.name_ar FROM geo.place l2
  WHERE l2.display_name = p.locality AND l2.name_ar IS NOT NULL
  ORDER BY l2.importance DESC LIMIT 1) l ON true
  WHERE p.kind = 'poi'
  AND st_dwithin(p.geog, st_setsrid(st_makepoint($3::float8, $2::float8), 4326)::geography, $4)
  AND movin.place_type_of(p.class, p.subclass, p.display_name) = $1
  ORDER BY p.geog <-> st_setsrid(st_makepoint($3::float8, $2::float8), 4326)::geography
  LIMIT $5;
\echo '--- cafés, Nouakchott, 5 km'
EXECUTE osm_of_type('cafe', 18.0858, -15.9785, 5000, 20);
\echo '--- cafés, Algiers, 5 km'
EXECUTE osm_of_type('cafe', 36.7538, 3.0588, 5000, 20);
\echo '--- markets, Nouakchott, 5 km'
EXECUTE osm_of_type('market', 18.0858, -15.9785, 5000, 20);
\echo '--- markets, Nouakchott, 15 km'
EXECUTE osm_of_type('market', 18.0858, -15.9785, 15000, 20);
\echo '--- pharmacies, Tamanrasset, 5 km'
EXECUTE osm_of_type('pharmacy', 22.7850, 5.5228, 5000, 20);
\echo '--- pharmacies, Tamanrasset, 15 km'
EXECUTE osm_of_type('pharmacy', 22.7850, 5.5228, 15000, 20);
\echo '--- mosques, Algiers, 15 km (no church in the list)'
EXECUTE osm_of_type('mosque', 36.7538, 3.0588, 15000, 20);
\echo '--- churches that place_type_of puts under mosque within 15 km of Algiers -- expect 0'
SELECT count(*) AS churches_as_mosques
  FROM geo.place p
 WHERE p.kind = 'poi'
   AND st_dwithin(p.geog, st_setsrid(st_makepoint(3.0588, 36.7538), 4326)::geography, 15000)
   AND movin.place_type_of(p.class, p.subclass, p.display_name) = 'mosque'
   AND p.display_name ~* '(église|eglise|cathédrale|cathedrale|chapelle|church|chapel|temple|كنيسة)';

\echo '=== 5. localitiesInArabic: the Arabic names the index holds for these localities'
PREPARE localities_ar AS
  SELECT DISTINCT ON (display_name) display_name, name_ar
  FROM geo.place
  WHERE display_name = ANY($1) AND name_ar IS NOT NULL
  ORDER BY display_name, importance DESC;
\echo '--- four localities'
EXECUTE localities_ar(ARRAY(SELECT DISTINCT locality FROM pg_temp.suggested_place WHERE locality IS NOT NULL) || ARRAY['Tevragh Zeina', 'Alger Centre']);

\echo '=== 6. approvedMatching (autocomplete), on the copy: approved only, nearest first'
PREPARE approved_matching AS
  select place_id, name as display_name, locality, 'poi' as kind,
  2 * 6371008.8 * asin(sqrt(
  power(sin(radians(lat - $2) / 2), 2)
  + cos(radians($2)) * cos(radians(lat)) * power(sin(radians(lon - $3) / 2), 2))) as distance_m
  from pg_temp.suggested_place
  where status = 'approved'
  and geo.normalise($1) <> ''
  and (strpos(geo.normalise(name), geo.normalise($1)) > 0
  or strpos(geo.normalise(coalesce(name_ar, '')), geo.normalise($1)) > 0)
  order by distance_m
  limit $4;
\echo '--- « tfeila » -> Café Sonde Tfeila'
EXECUTE approved_matching('tfeila', 18.0858, -15.9785, 3);
\echo '--- « المسبار » (Arabic name) -> the café, then the Algiers pharmacy'
EXECUTE approved_matching('المسبار', 18.0858, -15.9785, 3);
\echo '--- « attente » -> nothing (pending is never shown)'
EXECUTE approved_matching('attente', 18.0858, -15.9785, 3);
\echo '--- « %% » -> nothing (normalises to empty; % is not a wildcard)'
EXECUTE approved_matching('%%', 18.0858, -15.9785, 3);

\echo '=== 7. approvedPlace (details, geocode by id): u1 approved, u4 pending -> no row'
PREPARE approved_place AS
  select place_id, name as display_name, locality, 'poi' as kind, lat, lon, country
  from pg_temp.suggested_place
  where place_id = $1 and status = 'approved';
\echo '--- u1'
EXECUTE approved_place('u1');
\echo '--- u4 (expect no row)'
EXECUTE approved_place('u4');

\echo '=== 8. labels for u-ids: u1 and u3 (approved, with an Arabic name); not u2 (none), not u4 (pending)'
PREPARE labels AS
  select p.place_id,
  p.name_ar,
  p.locality,
  l.name_ar as locality_ar
  from pg_temp.suggested_place p
  left join lateral (
  select l2.name_ar
  from geo.place l2
  where l2.display_name = p.locality
  and l2.name_ar is not null
  order by l2.importance desc
  limit 1
  ) l on true
  where p.place_id = any($1)
  and p.status = 'approved'
  and p.name_ar is not null;
\echo '--- u1..u4'
EXECUTE labels(ARRAY['u1', 'u2', 'u3', 'u4']);

\echo '=== done: the copy and the prepared statements end with this session'
